<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Ubuntu Web Desktop</title>
<style>
* { box-sizing: border-box; margin: 0; padding: 0; }

html, body {
  height: 100%;
  overflow: hidden;
  font-family: 'Ubuntu', 'Segoe UI', 'Cantarell', system-ui, -apple-system, sans-serif;
  background: #000;
  color: #fff;
  -webkit-font-smoothing: antialiased;
}

#desktop {
  width: 100vw;
  height: 100vh;
  position: relative;
  overflow: hidden;
  background:
    radial-gradient(ellipse at 18% 22%, rgba(233, 84, 32, 0.18), transparent 55%),
    radial-gradient(ellipse at 82% 78%, rgba(118, 67, 158, 0.18), transparent 55%),
    radial-gradient(ellipse at 50% 50%, rgba(46, 92, 138, 0.12), transparent 70%),
    linear-gradient(135deg, #14142b 0%, #1f2347 50%, #0c0c1e 100%);
}

#desktop::before {
  content: '';
  position: absolute;
  inset: 0;
  background:
    repeating-linear-gradient(45deg, transparent 0 38px, rgba(255,255,255,0.012) 38px 39px),
    repeating-linear-gradient(-45deg, transparent 0 38px, rgba(255,255,255,0.008) 38px 39px);
  pointer-events: none;
}

/* Top bar (GNOME-style) */
#topbar {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 26px;
  background: rgba(12, 12, 12, 0.92);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  display: flex;
  align-items: center;
  padding: 0 12px;
  z-index: 100;
  font-size: 12px;
  font-weight: 500;
  user-select: none;
  border-bottom: 1px solid rgba(255,255,255,0.06);
}

#topbar .activities {
  font-weight: 700;
  color: #fff;
  cursor: pointer;
  padding: 2px 6px;
  border-radius: 3px;
  transition: background 0.15s;
}
#topbar .activities:hover { background: rgba(255,255,255,0.08); }

#topbar .app-name {
  margin-left: 14px;
  color: #ccc;
  font-weight: 600;
}

#topbar .spacer { flex: 1; }

#topbar .tray {
  display: flex;
  gap: 10px;
  margin-right: 14px;
  font-size: 11px;
  align-items: center;
}

#topbar .clock {
  color: #fff;
  font-variant-numeric: tabular-nums;
  font-weight: 500;
}

/* Dock */
#taskbar {
  position: absolute;
  left: 8px;
  top: 50%;
  transform: translateY(-50%);
  background: rgba(22, 22, 22, 0.82);
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
  border-radius: 14px;
  padding: 8px;
  display: flex;
  flex-direction: column;
  gap: 6px;
  z-index: 50;
  border: 1px solid rgba(255,255,255,0.08);
  box-shadow: 0 6px 24px rgba(0,0,0,0.5);
}

.launcher {
  width: 48px;
  height: 48px;
  border-radius: 10px;
  background: rgba(60, 60, 60, 0.85);
  border: 1px solid rgba(255,255,255,0.05);
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 24px;
  transition: transform 0.15s, background 0.15s;
  padding: 0;
  color: #fff;
  position: relative;
}

.launcher:hover {
  background: rgba(90, 90, 90, 0.95);
  transform: scale(1.06);
}

.launcher:active { transform: scale(0.95); }

.launcher::after {
  content: '';
  position: absolute;
  left: 50%;
  bottom: -10px;
  transform: translateX(-50%);
  width: 4px;
  height: 4px;
  background: #e95420;
  border-radius: 50%;
  opacity: 0;
  transition: opacity 0.15s;
}

.launcher.has-open::after { opacity: 1; }

/* Window base */
.window {
  position: absolute;
  background: #1e1e1e;
  color: #e0e0e0;
  border-radius: 10px;
  box-shadow:
    0 14px 44px rgba(0,0,0,0.65),
    0 2px 6px rgba(0,0,0,0.4),
    0 0 0 1px rgba(255,255,255,0.05);
  min-width: 360px;
  min-height: 240px;
  display: flex;
  flex-direction: column;
  overflow: hidden;
  animation: winOpen 0.18s cubic-bezier(0.4, 0, 0.2, 1);
}

@keyframes winOpen {
  from { opacity: 0; transform: translateY(12px) scale(0.97); }
  to   { opacity: 1; transform: translateY(0) scale(1); }
}

.window-titlebar {
  background: linear-gradient(to bottom, #303030, #262626);
  height: 34px;
  display: flex;
  align-items: center;
  padding: 0 6px 0 12px;
  cursor: move;
  user-select: none;
  border-bottom: 1px solid rgba(0,0,0,0.35);
}

.window-title {
  flex: 1;
  text-align: center;
  font-size: 12px;
  font-weight: 600;
  color: #d0d0d0;
  letter-spacing: 0.3px;
}

.win-close {
  background: transparent;
  border: none;
  color: #aaa;
  cursor: pointer;
  width: 28px;
  height: 28px;
  border-radius: 6px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 13px;
  font-weight: bold;
  transition: background 0.12s, color 0.12s;
}

.win-close:hover {
  background: #e74c3c;
  color: #fff;
}

.window-body {
  flex: 1;
  display: flex;
  flex-direction: column;
  overflow: hidden;
  background: #1e1e1e;
}

/* Files window */
#files-window {
  width: 660px;
  height: 440px;
  top: 80px;
  left: 180px;
}

#files-path-bar {
  display: flex;
  align-items: center;
  padding: 8px;
  background: #252525;
  gap: 8px;
  border-bottom: 1px solid #111;
}

#files-up {
  background: #333;
  border: 1px solid #444;
  color: #ddd;
  width: 30px;
  height: 30px;
  border-radius: 6px;
  cursor: pointer;
  font-size: 14px;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: background 0.12s;
}

#files-up:hover { background: #444; color: #fff; }
#files-up:disabled { opacity: 0.35; cursor: not-allowed; }

#files-path {
  flex: 1;
  background: #181818;
  padding: 6px 12px;
  border-radius: 6px;
  font-family: 'Ubuntu Mono', 'Consolas', 'Menlo', monospace;
  font-size: 12px;
  color: #a8c5e8;
  border: 1px solid #2a2a2a;
  overflow-x: auto;
  white-space: nowrap;
}

#files-list {
  flex: 1;
  overflow-y: auto;
  padding: 12px;
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(92px, 1fr));
  gap: 6px;
  align-content: start;
}

.fs-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 12px 6px;
  border-radius: 8px;
  cursor: pointer;
  transition: background 0.1s, border-color 0.1s;
  user-select: none;
  border: 1px solid transparent;
}

.fs-item:hover {
  background: rgba(255,255,255,0.06);
  border-color: rgba(255,255,255,0.05);
}

.fs-item.selected {
  background: rgba(233, 84, 32, 0.22);
  border-color: rgba(233, 84, 32, 0.35);
}

.fs-icon {
  font-size: 36px;
  margin-bottom: 6px;
  line-height: 1;
  filter: drop-shadow(0 1px 2px rgba(0,0,0,0.35));
}

.fs-name {
  font-size: 11px;
  text-align: center;
  word-break: break-word;
  color: #ddd;
  line-height: 1.25;
  max-width: 100%;
}

.fs-empty {
  grid-column: 1 / -1;
  padding: 50px;
  color: #666;
  text-align: center;
  font-size: 12px;
  font-style: italic;
}

/* Notepad window */
#notepad-window {
  width: 680px;
  height: 480px;
  top: 130px;
  left: 360px;
}

#tabs {
  display: flex;
  background: #1a1a1a;
  border-bottom: 1px solid #0d0d0d;
  overflow-x: auto;
  scrollbar-width: thin;
  align-items: stretch;
}

.tab {
  display: flex;
  align-items: center;
  padding: 0 10px;
  background: #161616;
  border-right: 1px solid #0a0a0a;
  cursor: pointer;
  font-size: 12px;
  color: #888;
  height: 32px;
  gap: 8px;
  min-width: 120px;
  max-width: 200px;
  flex-shrink: 0;
  position: relative;
  border-top: 2px solid transparent;
  transition: background 0.1s, color 0.1s;
}

.tab.active {
  background: #1e1e1e;
  color: #fff;
  border-top-color: #e95420;
}

.tab:hover {
  background: #1d1d1d;
  color: #ccc;
}

.tab-name {
  flex: 1;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  user-select: none;
}

.tab-close {
  background: transparent;
  border: none;
  color: #777;
  cursor: pointer;
  width: 18px;
  height: 18px;
  border-radius: 4px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 10px;
  padding: 0;
  flex-shrink: 0;
  transition: background 0.1s, color 0.1s;
}

.tab-close:hover {
  background: #444;
  color: #fff;
}

#new-tab {
  background: transparent;
  border: none;
  color: #888;
  padding: 0 14px;
  cursor: pointer;
  font-size: 18px;
  height: 32px;
  font-weight: 300;
  flex-shrink: 0;
  transition: background 0.1s, color 0.1s;
}

#new-tab:hover {
  background: rgba(255,255,255,0.06);
  color: #fff;
}

#editor {
  flex: 1;
  background: #1e1e1e;
  color: #e6e6e6;
  border: none;
  padding: 14px;
  font-family: 'Ubuntu Mono', 'Consolas', 'Menlo', 'Courier New', monospace;
  font-size: 13px;
  resize: none;
  outline: none;
  line-height: 1.6;
  tab-size: 4;
}

.hidden { display: none !important; }

/* Scrollbar */
::-webkit-scrollbar { width: 10px; height: 10px; }
::-webkit-scrollbar-track { background: #1a1a1a; }
::-webkit-scrollbar-thumb { background: #3a3a3a; border-radius: 5px; }
::-webkit-scrollbar-thumb:hover { background: #4a4a4a; }

/* Toast */
#toast {
  position: absolute;
  bottom: 24px;
  left: 50%;
  transform: translateX(-50%);
  background: rgba(40,40,40,0.95);
  color: #ddd;
  padding: 10px 18px;
  border-radius: 6px;
  font-size: 13px;
  z-index: 1000;
  border: 1px solid rgba(255,255,255,0.1);
  box-shadow: 0 4px 16px rgba(0,0,0,0.5);
  opacity: 0;
  transition: opacity 0.2s;
  pointer-events: none;
}
</style>
</head>
