<script>
(function() {
'use strict';

/* ===================== Filesystem (static) ===================== */
const filesystem = {
  '/': { dirs: ['bin', 'etc', 'home', 'usr', 'var'], files: [] },
  '/bin': { dirs: [], files: ['bash', 'ls', 'cat', 'cp', 'mv', 'rm', 'mkdir', 'chmod', 'chown', 'grep', 'find'] },
  '/etc': { dirs: ['init.d', 'network', 'systemd', 'ssh'], files: ['hostname', 'hosts', 'passwd', 'fstab', 'profile', 'resolv.conf', 'environment'] },
  '/etc/init.d': { dirs: [], files: ['networking', 'ssh', 'cron', 'apache2', 'mysql'] },
  '/etc/network': { dirs: [], files: ['interfaces', 'interfaces.d'] },
  '/etc/systemd': { dirs: [], files: ['system.conf', 'user.conf'] },
  '/etc/ssh': { dirs: [], files: ['sshd_config', 'ssh_config'] },
  '/home': { dirs: ['user'], files: [] },
  '/home/user': {
    dirs: ['Documents', 'Downloads', 'Pictures', 'Music', 'Videos', '.config', '.cache', '.local'],
    files: ['readme.txt', '.bashrc', '.profile', '.bash_history']
  },
  '/home/user/Documents': {
    dirs: ['Projects', 'Work'],
    files: ['notes.txt', 'report.txt', 'todo.md', 'presentation.odp', 'budget.csv']
  },
  '/home/user/Documents/Projects': {
    dirs: ['webapp', 'scripts'],
    files: ['README.md', 'changelog.txt']
  },
  '/home/user/Documents/Projects/webapp': {
    dirs: [], files: ['app.js', 'index.html', 'style.css', 'package.json']
  },
  '/home/user/Documents/Projects/scripts': {
    dirs: [], files: ['deploy.sh', 'backup.py']
  },
  '/home/user/Documents/Work': {
    dirs: [], files: ['meeting-notes.md', 'q1-summary.txt']
  },
  '/home/user/Downloads': { dirs: [], files: ['installer.deb', 'photo.jpg', 'archive.zip', 'setup.exe', 'presentation.pdf'] },
  '/home/user/Pictures': {
    dirs: ['Wallpapers', 'Screenshots', 'Vacation'],
    files: ['wallpaper.png', 'photo1.jpg', 'profile.png']
  },
  '/home/user/Pictures/Wallpapers': {
    dirs: [], files: ['ubuntu-default.jpg', 'dark.png', 'mountain.jpg', 'aurora.jpg', 'forest.jpg']
  },
  '/home/user/Pictures/Screenshots': {
    dirs: [], files: ['screenshot-2024-01-15.png', 'screenshot-2024-02-03.png', 'screenshot-2024-03-22.png']
  },
  '/home/user/Pictures/Vacation': {
    dirs: [], files: ['beach.jpg', 'sunset.jpg', 'mountain.jpg']
  },
  '/home/user/Music': { dirs: [], files: ['song.mp3', 'album.flac', 'playlist.m3u', 'podcast.mp3'] },
  '/home/user/Videos': { dirs: [], files: ['movie.mp4', 'clip.webm', 'tutorial.mkv'] },
  '/home/user/.config': { dirs: ['gtk-3.0', 'nano', 'code'], files: ['user-dirs.dirs', 'mimeapps.list'] },
  '/home/user/.config/gtk-3.0': { dirs: [], files: ['settings.ini', 'bookmarks'] },
  '/home/user/.config/nano': { dirs: [], files: ['nanorc'] },
  '/home/user/.config/code': { dirs: ['snippets'], files: ['settings.json'] },
  '/home/user/.config/code/snippets': { dirs: [], files: ['javascript.json'] },
  '/home/user/.cache': { dirs: [], files: ['recently-used.xbel', 'thumbnails'] },
  '/home/user/.local': { dirs: ['share'], files: [] },
  '/home/user/.local/share': { dirs: ['applications'], files: ['trashinfo'] },
  '/home/user/.local/share/applications': { dirs: [], files: ['myapp.desktop'] },
  '/usr': { dirs: ['bin', 'lib', 'share', 'local', 'include', 'sbin'], files: [] },
  '/usr/bin': { dirs: [], files: ['firefox', 'gnome-terminal', 'gedit', 'nautilus', 'python3', 'node', 'vim', 'nano'] },
  '/usr/lib': { dirs: ['firefox', 'python3'], files: ['libc.so', 'libm.so', 'libpthread.so'] },
  '/usr/lib/firefox': { dirs: [], files: ['firefox-bin', 'omni.ja', 'libnss3.so'] },
  '/usr/lib/python3': { dirs: [], files: ['os.py', 'sys.py', 'site.py'] },
  '/usr/share': { dirs: ['themes', 'icons', 'fonts', 'applications', 'doc'], files: ['info'] },
  '/usr/share/themes': { dirs: [], files: ['Yaru', 'Adwaita', 'Adwaita-dark', 'HighContrast'] },
  '/usr/share/icons': { dirs: [], files: ['Yaru', 'Papirus', 'Adwaita', 'hicolor'] },
  '/usr/share/fonts': { dirs: ['truetype'], files: [] },
  '/usr/share/fonts/truetype': { dirs: [], files: ['ubuntu', 'dejavu'] },
  '/usr/share/applications': { dirs: [], files: ['firefox.desktop', 'gedit.desktop', 'nautilus.desktop'] },
  '/usr/share/doc': { dirs: [], files: ['copyright', 'README'] },
  '/usr/local': { dirs: ['bin', 'lib', 'share'], files: [] },
  '/usr/local/bin': { dirs: [], files: [] },
  '/usr/local/lib': { dirs: [], files: [] },
  '/usr/local/share': { dirs: [], files: [] },
  '/usr/include': { dirs: [], files: ['stdio.h', 'stdlib.h', 'string.h'] },
  '/usr/sbin': { dirs: [], files: ['sshd', 'cron'] },
  '/var': { dirs: ['log', 'tmp', 'cache', 'lib', 'mail'], files: [] },
  '/var/log': { dirs: [], files: ['syslog', 'auth.log', 'kern.log', 'dmesg', 'dpkg.log', 'Xorg.0.log'] },
  '/var/tmp': { dirs: [], files: [] },
  '/var/cache': { dirs: ['apt'], files: [] },
  '/var/cache/apt': { dirs: ['archives'], files: ['pkgcache.bin', 'srcpkgcache.bin'] },
  '/var/cache/apt/archives': { dirs: [], files: ['firefox.deb', 'libreoffice.deb', 'gimp.deb'] },
  '/var/lib': { dirs: ['apt', 'dpkg'], files: [] },
  '/var/lib/apt': { dirs: [], files: ['extended_states', 'lists'] },
  '/var/lib/dpkg': { dirs: [], files: ['status', 'available', 'info'] },
  '/var/mail': { dirs: [], files: [] }
};

const FILE_ICONS = {
  txt: '📄', md: '📝', json: '📋', js: '📜', html: '🌐', css: '🎨',
  jpg: '🖼️', jpeg: '🖼️', png: '🖼️', gif: '🖼️', svg: '🖼️', bmp: '🖼️',
  mp3: '🎵', wav: '🎵', flac: '🎵', m3u: '🎵', ogg: '🎵',
  mp4: '🎬', webm: '🎬', mkv: '🎬', avi: '🎬',
  zip: '🗜️', tar: '🗜️', gz: '🗜️', '7z': '🗜️', rar: '🗜️',
  deb: '📦', exe: '⚙️', msi: '⚙️',
  sh: '🐚', py: '🐍', conf: '⚙️', ini: '⚙️',
  so: '⚙️', h: '📘', c: '📘',
  odp: '📊', odt: '📄', pdf: '📕', csv: '📊',
  desktop: '🚀'
};

function getFileIcon(name) {
  const dot = name.lastIndexOf('.');
  if (dot === -1) return '📄';
  const ext = name.substring(dot + 1).toLowerCase();
  return FILE_ICONS[ext] || '📄';
}

function getParent(path) {
  if (path === '/') return null;
  const parts = path.split('/').filter(Boolean);
  parts.pop();
  return '/' + parts.join('/');
}

function escapeHtml(s) {
  return String(s).replace(/[&<>"']/g, c => ({
    '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;'
  }[c]));
}

/* ===================== Files App ===================== */
let currentPath = '/';
const filesPathEl = document.getElementById('files-path');
const filesListEl = document.getElementById('files-list');
const filesUpEl = document.getElementById('files-up');

function renderFiles() {
  filesPathEl.textContent = currentPath;
  filesUpEl.disabled = (currentPath === '/');
  filesListEl.innerHTML = '';

  const node = filesystem[currentPath];
  if (!node) {
    const err = document.createElement('div');
    err.className = 'fs-empty';
    err.textContent = 'Path not found';
    filesListEl.appendChild(err);
    return;
  }

  // Directories first
  node.dirs.forEach(name => {
    const el = document.createElement('div');
    el.className = 'fs-item';
    el.innerHTML = `<div class="fs-icon">📁</div><div class="fs-name">${escapeHtml(name)}</div>`;
    el.title = name;
    el.addEventListener('dblclick', () => {
      const newPath = currentPath === '/' ? '/' + name : currentPath + '/' + name;
      if (filesystem[newPath] !== undefined) {
        currentPath = newPath;
        renderFiles();
      } else {
        showToast('Folder not accessible');
      }
    });
    filesListEl.appendChild(el);
  });

  // Files
  node.files.forEach(name => {
    const el = document.createElement('div');
    el.className = 'fs-item';
    const icon = getFileIcon(name);
    el.innerHTML = `<div class="fs-icon">${icon}</div><div class="fs-name">${escapeHtml(name)}</div>`;
    el.title = name;
    el.addEventListener('dblclick', () => {
      showToast(`No application installed to open "${name}"`);
    });
    filesListEl.appendChild(el);
  });

  if (node.dirs.length === 0 && node.files.length === 0) {
    const empty = document.createElement('div');
    empty.className = 'fs-empty';
    empty.textContent = 'This folder is empty';
    filesListEl.appendChild(empty);
  }
}

filesUpEl.addEventListener('click', () => {
  const parent = getParent(currentPath);
  if (parent !== null) {
    currentPath = parent;
    renderFiles();
  }
});

/* ===================== Window Management ===================== */
let topZ = 100;

function bringToFront(win) {
  topZ += 1;
  win.style.zIndex = String(topZ);
}

function makeDraggable(win) {
  const titlebar = win.querySelector('.window-titlebar');
  let isDragging = false;
  let startX = 0, startY = 0, startLeft = 0, startTop = 0;

  titlebar.addEventListener('mousedown', (e) => {
    if (e.target.classList.contains('win-close')) return;
    if (e.button !== 0) return;
    isDragging = true;
    startX = e.clientX;
    startY = e.clientY;
    const rect = win.getBoundingClientRect();
    startLeft = rect.left;
    startTop = rect.top;
    bringToFront(win);
    e.preventDefault();
  });

  document.addEventListener('mousemove', (e) => {
    if (!isDragging) return;
    const deskRect = document.getElementById('desktop').getBoundingClientRect();
    let newLeft = startLeft + (e.clientX - startX);
    let newTop = startTop + (e.clientY - startY);
    // Keep titlebar visible at all times
    newLeft = Math.max(-win.offsetWidth + 60, Math.min(newLeft, deskRect.width - 60));
    newTop = Math.max(26, Math.min(newTop, deskRect.height - 28));
    win.style.left = newLeft + 'px';
    win.style.top = newTop + 'px';
  });

  document.addEventListener('mouseup', () => {
    isDragging = false;
  });
}

function updateDockIndicators() {
  const filesVisible = !document.getElementById('files-window').classList.contains('hidden');
  const notepadVisible = !document.getElementById('notepad-window').classList.contains('hidden');
