/* ===================== Notepad App ===================== */
const STORAGE_KEY = 'ubuntu-web-notepad-v1';
let tabs = [];
let activeTabId = null;
let tabIdCounter = 0;

const tabsEl = document.getElementById('tabs');
const editorEl = document.getElementById('editor');
const newTabBtn = document.getElementById('new-tab');

function loadTabs() {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (raw) {
      const data = JSON.parse(raw);
      if (data && Array.isArray(data.tabs) && data.tabs.length > 0) {
        // Validate
        const clean = data.tabs
          .filter(t => t && typeof t.id === 'number' && typeof t.name === 'string')
          .map(t => ({ id: t.id, name: t.name, content: typeof t.content === 'string' ? t.content : '' }));
        if (clean.length > 0) {
          tabs = clean;
          activeTabId = tabs.some(t => t.id === data.activeTabId) ? data.activeTabId : tabs[0].id;
          tabIdCounter = Math.max(
            typeof data.counter === 'number' ? data.counter : 0,
            ...tabs.map(t => t.id)
          );
          return;
        }
      }
    }
  } catch (e) {
    // fall through to default
  }
  createTab('Untitled', false);
}

function saveTabs() {
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify({
      tabs: tabs,
      activeTabId: activeTabId,
      counter: tabIdCounter
    }));
  } catch (e) {}
}

function createTab(name, save = true) {
  const tab = {
    id: ++tabIdCounter,
    name: name || 'Untitled',
    content: ''
  };
  tabs.push(tab);
  activeTabId = tab.id;
  if (save) saveTabs();
  renderTabs();
  updateEditor();
  return tab;
}

function renderTabs() {
  // Remove existing tab elements (keep #new-tab)
  Array.from(tabsEl.querySelectorAll('.tab')).forEach(t => t.remove());

  tabs.forEach(tab => {
    const tabEl = document.createElement('div');
    tabEl.className = 'tab' + (tab.id === activeTabId ? ' active' : '');
    tabEl.dataset.id = String(tab.id);
    tabEl.innerHTML = `<span class="tab-name">${escapeHtml(tab.name)}</span><button class="tab-close" aria-label="Close tab">✕</button>`;

    tabEl.addEventListener('click', (e) => {
      if (e.target.classList.contains('tab-close')) {
        e.stopPropagation();
        closeTab(tab.id);
        return;
      }
      if (activeTabId !== tab.id) {
        activeTabId = tab.id;
        saveTabs();
        renderTabs();
        updateEditor();
      }
      editorEl.focus();
    });

    tabsEl.insertBefore(tabEl, newTabBtn);
  });
}

function closeTab(id) {
  const idx = tabs.findIndex(t => t.id === id);
  if (idx === -1) return;

  const wasActive = (activeTabId === id);
  tabs.splice(idx, 1);

  if (wasActive) {
    if (tabs.length > 0) {
      // Prefer the tab that took the removed tab's slot (i.e. next sibling)
      activeTabId = tabs[idx] ? tabs[idx].id : tabs[idx - 1].id;
    } else {
      activeTabId = null;
    }
  }

  if (tabs.length === 0) {
    createTab('Untitled');
    return;
  }

  saveTabs();
  renderTabs();
  updateEditor();
}

function updateEditor() {
  const tab = tabs.find(t => t.id === activeTabId);
  editorEl.value = tab ? tab.content : '';
}

editorEl.addEventListener('input', () => {
  const tab = tabs.find(t => t.id === activeTabId);
  if (tab) {
    tab.content = editorEl.value;
    saveTabs();
  }
});

// Prevent tab key in textarea from losing focus; insert spaces instead
editorEl.addEventListener('keydown', (e) => {
  if (e.key === 'Tab') {
    e.preventDefault();
    const start = editorEl.selectionStart;
    const end = editorEl.selectionEnd;
    const v = editorEl.value;
    editorEl.value = v.substring(0, start) + '    ' + v.substring(end);
    editorEl.selectionStart = editorEl.selectionEnd = start + 4;
    editorEl.dispatchEvent(new Event('input'));
  }
});

newTabBtn.addEventListener('click', (e) => {
  e.stopPropagation();
  createTab('Untitled');
  editorEl.focus();
});

// Keyboard shortcut: Ctrl+T for new tab when notepad is open
